type Place = {
    name: string
    cc: string
    lat: number
    lng: number
    cap: boolean
}

function parsePlaces(src: string, isCity: boolean): Place[] {
    const out: Place[] = []
    if (!src) return out
    for (const rec of src.split("~")) {
        const f = rec.split("|")
        if (f.length < 4) continue
        out.push({
            name: f[0],
            cc: f[1],
            lat: Number(f[2]) / 100,
            lng: Number(f[3]) / 100,
            cap: isCity && f[4] === "1",
        })
    }
    return out
}

const CITY_LIST = parsePlaces(CITIES, true)
const COUNTRY_LIST = parsePlaces(COUNTRIES, false)

// Strip accents / punctuation so "Bogotá" matches "bogota".
function norm(s: string) {
    return (s || "")
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .replace(/[^a-z0-9 ]/g, "")
        .trim()
}

// Index built once: place name (and "city, cc") → coordinates.
const INDEX: Map<string, Place> = (() => {
    const m = new Map<string, Place>()
    // countries first, cities win on collision (more specific query intent)
    for (const p of COUNTRY_LIST) {
        m.set(norm(p.name), p)
        m.set(norm(p.cc), p)
    }
    for (const p of CITY_LIST) {
        const n = norm(p.name)
        const existing = m.get(n)
        // prefer capitals / first occurrence for duplicate city names
        if (!existing || (p.cap && !existing.cap)) m.set(n, p)
        m.set(n + " " + norm(p.cc), p)
    }
    return m
})()

/** Resolve a free-text place name to coordinates. Returns null if unknown. */
function lookupPlace(query: string): Place | null {
    const q = norm(query)
    if (!q) return null
    const exact = INDEX.get(q)
    if (exact) return exact
    // "City, Country" → try the part before the comma
    const head = norm(query.split(",")[0])
    if (head && head !== q) {
        const h = INDEX.get(head)
        if (h) return h
    }
    // last resort: unique prefix match
    let hit: Place | null = null
    let count = 0
    for (const [k, v] of INDEX) {
        if (k.startsWith(q)) {
            hit = v
            if (++count > 1) break
        }
    }
    return count === 1 ? hit : hit
}

type Marker = {
    mode: "search" | "coords"
    place: string
    lat: number
    lng: number
    label: string
    type: "dot" | "image" | "video"
    image?: string
    video?: string
    color: string
    size: number
}

type PointImage = { image?: string }

type Props = {
    background: string
    pointCount: number
    pointImages: PointImage[]
    pointShape: "circle" | "rounded" | "square"
    imageSize: number
    shuffleImages: boolean
    dotColor: string
    dotSize: number
    glow: boolean
    globeScale: number
    autoRotate: boolean
    speed: number
    tilt: number
    draggable: boolean
    friction: number
    hideBack: boolean
    introEnabled: boolean
    introDuration: number
    introOrder: "random" | "sweep" | "center"
    introSlide: boolean
    markers: Marker[]
    markerShape: "circle" | "rounded" | "square"
    markerRing: boolean
    markerRingColor: string
    showTags: boolean
    tagFont: number
    tagColor: string
    tagBackground: string
    tagOffset: number
    tagFadeBack: boolean
    style?: React.CSSProperties
}

function clamp(v: number, lo: number, hi: number) {
    return Math.min(hi, Math.max(lo, v))
}

// Easy-ease (cubic in-out): slow start, quick middle, soft landing.
function easeInOut(t: number) {
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
}

function prefersReduced() {
    return (
        typeof window !== "undefined" &&
        !!window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
    )
}

function mulberry32(a: number) {
    return function () {
        a |= 0
        a = (a + 0x6d2b79f5) | 0
        let t = Math.imul(a ^ (a >>> 15), 1 | a)
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296
    }
}

// lat/lng (deg) → unit vector on the sphere (y up).
function toVec(lat: number, lng: number) {
    const la = (lat * Math.PI) / 180
    const lo = (lng * Math.PI) / 180
    const cl = Math.cos(la)
    return { x: cl * Math.sin(lo), y: Math.sin(la), z: cl * Math.cos(lo) }
}

export default function DottedGlobe(props: Props) {
    const {
        background,
        pointCount,
        pointImages,
        pointShape,
        imageSize,
        shuffleImages,
        dotColor,
        dotSize,
        glow,
        globeScale,
        autoRotate,
        speed,
        tilt,
        draggable,
        friction,
        hideBack,
        introEnabled,
        introDuration,
        introOrder,
        introSlide,
        markers,
        markerShape,
        markerRing,
        markerRingColor,
        showTags,
        tagFont,
        tagColor,
        tagBackground,
        tagOffset,
        tagFadeBack,
        style,
    } = props

    // True on the Framer canvas and during export/thumbnail rendering.
    const isStatic = useIsStaticRenderer()
    const wrapRef = useRef<HTMLDivElement>(null)
    const canvasRef = useRef<HTMLCanvasElement>(null)
    const markerRefs = useRef<HTMLDivElement[]>([])
    const tagRefs = useRef<HTMLDivElement[]>([])

    // Subsample the land points down to the requested count.
    const pts = useMemo(() => {
        const target = clamp(Math.round(pointCount), 30, TOTAL)
        const stride = Math.max(1, Math.floor(TOTAL / target))
        const out: { x: number; y: number; z: number }[] = []
        for (let i = 0; i < LAND.length; i += 2 * stride) {
            out.push(toVec(LAND[i] / 100, LAND[i + 1] / 100))
        }
        return out
    }, [pointCount])

    const imageUrls = useMemo(
        () =>
            (pointImages ?? []).map((p) => p.image).filter(Boolean) as string[],
        [pointImages]
    )
    const usingImages = imageUrls.length > 0

    const imgIndex = useMemo(() => {
        const n = Math.max(1, imageUrls.length)
        if (!shuffleImages) return pts.map((_, i) => i % n)
        const rnd = mulberry32(1234 + n)
        return pts.map(() => Math.floor(rnd() * n))
    }, [pts, imageUrls.length, shuffleImages])

    // Pre-render each image into a clipped sprite once.
    const spritesRef = useRef<HTMLCanvasElement[]>([])
    const readyRef = useRef<boolean[]>([])
    // Always points at the latest draw(), so async callbacks can repaint.
    const drawRef = useRef<(() => void) | null>(null)
    useEffect(() => {
        const S = 160
        const sprites: HTMLCanvasElement[] = []
        const ready: boolean[] = []
        imageUrls.forEach((url, idx) => {
            const c = document.createElement("canvas")
            c.width = S
            c.height = S
            sprites[idx] = c
            ready[idx] = false
            const img = new Image()
            img.crossOrigin = "anonymous"
            img.onload = () => {
                const cx = c.getContext("2d")
                if (!cx) return
                cx.clearRect(0, 0, S, S)
                cx.save()
                if (pointShape === "circle") {
                    cx.beginPath()
                    cx.arc(S / 2, S / 2, S / 2, 0, Math.PI * 2)
                    cx.clip()
                } else if (pointShape === "rounded") {
                    const r = S * 0.22
                    cx.beginPath()
                    cx.moveTo(r, 0)
                    cx.arcTo(S, 0, S, S, r)
                    cx.arcTo(S, S, 0, S, r)
                    cx.arcTo(0, S, 0, 0, r)
                    cx.arcTo(0, 0, S, 0, r)
                    cx.closePath()
                    cx.clip()
                }
                const ar = img.width / img.height
                let dw = S,
                    dh = S,
                    dx = 0,
                    dy = 0
                if (ar > 1) {
                    dh = S
                    dw = S * ar
                    dx = (S - dw) / 2
                } else {
                    dw = S
                    dh = S / ar
                    dy = (S - dh) / 2
                }
                cx.drawImage(img, dx, dy, dw, dh)
                cx.restore()
                ready[idx] = true
                // Repaint once this sprite is ready. Event driven, so static
                // renderers never need a polling timer to catch late images.
                drawRef.current?.()
            }
            img.src = url
        })
        spritesRef.current = sprites
        readyRef.current = ready
    }, [imageUrls, pointShape])

    // Resolve every marker: either a searched place name or raw coordinates.
    const resolved = useMemo(() => {
        return (markers ?? []).map((m) => {
            let lat = m.lat
            let lng = m.lng
            let found: Place | null = null
            if (m.mode !== "coords" && m.place) {
                found = lookupPlace(m.place)
                if (found) {
                    lat = found.lat
                    lng = found.lng
                }
            }
            const label =
                m.label && m.label.trim().length > 0
                    ? m.label
                    : found
                      ? found.name
                      : m.place || ""
            return {
                ...m,
                lat,
                lng,
                label,
                vec: toVec(lat, lng),
                found: !!found,
            }
        })
    }, [markers])

    const rot = useRef({ x: (tilt * Math.PI) / 180, y: 0 })
    const vel = useRef({ x: 0, y: 0 })
    const drag = useRef({ active: false, lastX: 0, lastY: 0 })
    const view = useRef({ w: 560, h: 560, dpr: 1 })
    const rafRef = useRef<number>(0)

    // ----- Intro reveal -----
    // Each point gets a start offset, so they pop in one by one instead of
    // the whole globe appearing at once. Delays are normalised 0..1 and
    // scaled by introDuration at draw time.
    const introDelays = useMemo(() => {
        const n = pts.length
        if (n === 0) return [] as number[]
        if (introOrder === "sweep") {
            // LAND is ordered by latitude band, so index order wipes pole to pole.
            return pts.map((_, i) => i / n)
        }
        if (introOrder === "center") {
            // Nearest the front of the globe first, rippling outward.
            let min = Infinity
            let max = -Infinity
            for (const p of pts) {
                if (p.z < min) min = p.z
                if (p.z > max) max = p.z
            }
            const span = max - min || 1
            return pts.map((p) => 1 - (p.z - min) / span)
        }
        // "random": deterministic shuffle so the sparkle is stable per render.
        const rnd = mulberry32(97 + n)
        return pts.map(() => rnd())
    }, [pts, introOrder])

    // Timestamp the reveal starts. Restarting it re-runs the animation.
    const introStart = useRef<number>(0)
    const introDone = useRef(false)
    useEffect(() => {
        introStart.current = 0 // set on the first frame of the loop
        introDone.current = false
    }, [introEnabled, introDuration, introOrder, pts, introSlide])

    const markerRadius =
        markerShape === "circle"
            ? "50%"
            : markerShape === "rounded"
              ? "22%"
              : "0%"

    const draw = useCallback(() => {
        const canvas = canvasRef.current
        if (!canvas) return
        const ctx = canvas.getContext("2d")
        if (!ctx) return
        const vw = view.current.w
        const vh = view.current.h
        const cx = vw / 2
        const cy = vh / 2
        const radius = (Math.min(vw, vh) / 2) * globeScale
        const perspective = radius * 2.4

        const { x: rx, y: ry } = rot.current
        const cosX = Math.cos(rx)
        const sinX = Math.sin(rx)
        const cosY = Math.cos(ry)
        const sinY = Math.sin(ry)

        ctx.setTransform(view.current.dpr, 0, 0, view.current.dpr, 0, 0)
        ctx.clearRect(0, 0, vw, vh)

        // Intro progress for this frame. EACH_MS is how long a single point
        // takes to fade in; the rest of introDuration is spent staggering.
        const now = performance.now()
        if (introStart.current === 0) introStart.current = now
        // The Framer canvas shows the settled state, never the reveal.
        const introOn =
            introEnabled && !introDone.current && !isStatic && !prefersReduced()
        const elapsed = now - introStart.current
        const EACH_MS = Math.max(80, introDuration * 0.35)
        const spread = Math.max(1, introDuration - EACH_MS)
        if (introOn && elapsed >= introDuration + 40) introDone.current = true

        const sprites = spritesRef.current
        const ready = readyRef.current

        if (!usingImages) {
            ctx.fillStyle = dotColor
            if (glow) {
                ctx.shadowBlur = dotSize * 2.2
                ctx.shadowColor = dotColor
            } else {
                ctx.shadowBlur = 0
            }
        }

        for (let i = 0; i < pts.length; i++) {
            const p = pts[i]
            const x1 = p.x * cosY + p.z * sinY
            const z1 = -p.x * sinY + p.z * cosY
            const y1 = p.y
            const y2 = y1 * cosX - z1 * sinX
            const z2 = y1 * sinX + z1 * cosX
            if (hideBack && z2 < -0.02) continue
            const depth = (z2 + 1) / 2
            const persp = perspective / (perspective - z2 * radius)
            let alpha = clamp((z2 + 0.25) / 0.6, 0, 1) * (0.35 + 0.65 * depth)

            // Ease-in-out fade in, staggered per point.
            let intro = 1
            if (introOn) {
                intro = easeInOut(
                    clamp((elapsed - introDelays[i] * spread) / EACH_MS, 0, 1)
                )
                if (intro <= 0) continue
                alpha *= intro
            }
            if (alpha <= 0.02) continue
            const px = cx + x1 * radius
            const py = cy + y2 * radius
            // Points also ease up to full size as they land.
            const introScale = introSlide ? 0.35 + 0.65 * intro : 1

            if (usingImages) {
                const spr = sprites[imgIndex[i]]
                const rd = ready[imgIndex[i]]
                const half =
                    imageSize * persp * (0.55 + 0.45 * depth) * 0.5 * introScale
                ctx.globalAlpha = alpha
                if (spr && rd) {
                    ctx.drawImage(spr, px - half, py - half, half * 2, half * 2)
                } else {
                    ctx.fillStyle = dotColor
                    ctx.beginPath()
                    ctx.arc(px, py, Math.max(1, half * 0.5), 0, Math.PI * 2)
                    ctx.fill()
                }
            } else {
                const r =
                    dotSize * persp * (0.45 + 0.55 * depth) * 0.5 * introScale
                ctx.globalAlpha = alpha
                ctx.beginPath()
                ctx.arc(px, py, Math.max(0.4, r), 0, Math.PI * 2)
                ctx.fill()
            }
        }
        ctx.globalAlpha = 1
        ctx.shadowBlur = 0

        // Markers land after the globe has mostly drawn itself in.
        const markerIntro = introOn
            ? easeInOut(
                  clamp(
                      (elapsed - introDuration * 0.55) / (introDuration * 0.5),
                      0,
                      1
                  )
              )
            : 1

        // Position HTML markers + their tags over the globe.
        const nodes = markerRefs.current
        const tags = tagRefs.current
        for (let i = 0; i < resolved.length; i++) {
            const m = resolved[i]
            const p = m.vec
            const x1 = p.x * cosY + p.z * sinY
            const z1 = -p.x * sinY + p.z * cosY
            const y1 = p.y
            const y2 = y1 * cosX - z1 * sinX
            const z2 = y1 * sinX + z1 * cosX
            const depth = (z2 + 1) / 2
            const persp = perspective / (perspective - z2 * radius)
            const scale =
                persp * (0.7 + 0.3 * depth) * (0.4 + 0.6 * markerIntro)
            const opacity = clamp((z2 + 0.1) / 0.4, 0, 1) * markerIntro
            const px = cx + x1 * radius
            const py = cy + y2 * radius
            const z = Math.round(depth * 1000)

            const node = nodes[i]
            if (node) {
                node.style.transform = `translate3d(${px}px, ${py}px, 0) scale(${scale}) translate(-50%, -50%)`
                node.style.opacity = String(opacity)
                node.style.zIndex = String(z)
                node.style.visibility = opacity <= 0.01 ? "hidden" : "visible"
            }
            const tag = tags[i]
            if (tag) {
                const ty = py - (m.size / 2) * scale - tagOffset
                tag.style.transform = `translate3d(${px}px, ${ty}px, 0) translate(-50%, -100%)`
                const tOpacity = tagFadeBack ? opacity : opacity > 0.01 ? 1 : 0
                tag.style.opacity = String(tOpacity)
                tag.style.zIndex = String(z + 1)
                tag.style.visibility = tOpacity <= 0.01 ? "hidden" : "visible"
            }
        }
    }, [
        pts,
        usingImages,
        imgIndex,
        imageSize,
        resolved,
        dotColor,
        dotSize,
        glow,
        globeScale,
        hideBack,
        tagOffset,
        tagFadeBack,
        introEnabled,
        introDuration,
        introDelays,
        introSlide,
    ])

    // Measure + size the canvas for the device pixel ratio.
    useEffect(() => {
        const wrap = wrapRef.current
        const canvas = canvasRef.current
        if (!wrap || !canvas) return
        const measure = () => {
            const r = wrap.getBoundingClientRect()
            const dpr = Math.min(2, window.devicePixelRatio || 1)
            view.current = { w: r.width, h: r.height, dpr }
            canvas.width = Math.round(r.width * dpr)
            canvas.height = Math.round(r.height * dpr)
            draw()
        }
        measure()
        const ro = new ResizeObserver(measure)
        ro.observe(wrap)
        return () => ro.disconnect()
    }, [draw])

    useEffect(() => {
        drawRef.current = draw
    }, [draw])

    // Animation loop. Static renderers (canvas + export) get a single frame
    // and no loop at all, so the editor stays fast and exports do not tile.
    useEffect(() => {
        rot.current.x = (tilt * Math.PI) / 180
        if (isStatic) {
            draw()
            return
        }
        const reduce =
            typeof window !== "undefined" &&
            window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
        let last = performance.now()
        const loop = (now: number) => {
            const dt = Math.min(64, now - last) / 16.6667
            last = now
            if (!drag.current.active) {
                if (autoRotate && !reduce) {
                    rot.current.y += speed * 0.0022 * dt + vel.current.y * dt
                    rot.current.x += vel.current.x * dt
                } else {
                    rot.current.y += vel.current.y * dt
                    rot.current.x += vel.current.x * dt
                }
                const f = Math.pow(friction, dt)
                vel.current.x *= f
                vel.current.y *= f
            }
            rot.current.x = clamp(rot.current.x, -Math.PI / 2.1, Math.PI / 2.1)
            draw()
            rafRef.current = requestAnimationFrame(loop)
        }
        rafRef.current = requestAnimationFrame(loop)
        return () => cancelAnimationFrame(rafRef.current)
    }, [isStatic, autoRotate, speed, friction, tilt, draw])

    const onPointerDown = useCallback(
        (e: React.PointerEvent) => {
            if (!draggable || isStatic) return
            drag.current.active = true
            drag.current.lastX = e.clientX
            drag.current.lastY = e.clientY
            vel.current.x = 0
            vel.current.y = 0
            ;(e.currentTarget as Element).setPointerCapture?.(e.pointerId)
        },
        [draggable, isStatic]
    )

    const onPointerMove = useCallback(
        (e: React.PointerEvent) => {
            if (!drag.current.active) return
            const dx = e.clientX - drag.current.lastX
            const dy = e.clientY - drag.current.lastY
            drag.current.lastX = e.clientX
            drag.current.lastY = e.clientY
            const s = 0.006
            rot.current.y += dx * s
            rot.current.x -= dy * s
            vel.current.y = dx * s
            vel.current.x = -dy * s
            draw()
        },
        [draw]
    )

    const endDrag = useCallback((e: React.PointerEvent) => {
        if (!drag.current.active) return
        drag.current.active = false
        ;(e.currentTarget as Element).releasePointerCapture?.(e.pointerId)
    }, [])

    return (
        <div
            ref={wrapRef}
            style={{
                position: "relative",
                width: "100%",
                height: "100%",
                overflow: "hidden",
                background,
                touchAction: "none",
                cursor: draggable && !isStatic ? "grab" : "default",
                userSelect: "none",
                ...style,
            }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={endDrag}
            onPointerCancel={endDrag}
        >
            <canvas
                ref={canvasRef}
                style={{ width: "100%", height: "100%", display: "block" }}
            />
            <div
                style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    width: 0,
                    height: 0,
                }}
            >
                {resolved.map((m, i) => (
                    <div
                        key={"m" + i}
                        ref={(el) => {
                            if (el) markerRefs.current[i] = el
                        }}
                        style={{
                            position: "absolute",
                            left: 0,
                            top: 0,
                            width: m.size,
                            height: m.size,
                            borderRadius: markerRadius,
                            overflow: "hidden",
                            transformOrigin: "center",
                            background:
                                m.type === "dot" ? m.color : "transparent",
                            boxShadow: markerRing
                                ? `0 0 0 2px ${markerRingColor}`
                                : "none",
                            willChange: "transform, opacity",
                            visibility: "hidden",
                            pointerEvents: "none",
                        }}
                    >
                        {m.type === "image" && m.image && (
                            <img
                                src={m.image}
                                alt=""
                                draggable={false}
                                style={{
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "cover",
                                    display: "block",
                                }}
                            />
                        )}
                        {m.type === "video" && m.video && !isStatic && (
                            <video
                                src={m.video}
                                muted
                                loop
                                autoPlay
                                playsInline
                                style={{
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "cover",
                                    display: "block",
                                }}
                            />
                        )}
                        {m.type === "video" && isStatic && (
                            <div
                                style={{
                                    width: "100%",
                                    height: "100%",
                                    background: m.color,
                                }}
                            />
                        )}
                    </div>
                ))}

                {showTags &&
                    resolved.map((m, i) =>
                        m.label ? (
                            <div
                                key={"t" + i}
                                ref={(el) => {
                                    if (el) tagRefs.current[i] = el
                                }}
                                style={{
                                    position: "absolute",
                                    left: 0,
                                    top: 0,
                                    padding: `${Math.round(tagFont * 0.32)}px ${Math.round(tagFont * 0.6)}px`,
                                    borderRadius: 999,
                                    background: tagBackground,
                                    color: tagColor,
                                    fontSize: tagFont,
                                    lineHeight: 1.25,
                                    fontWeight: 500,
                                    whiteSpace: "nowrap",
                                    willChange: "transform, opacity",
                                    visibility: "hidden",
                                    pointerEvents: "none",
                                }}
                            >
                                {m.label}
                            </div>
                        ) : null
                    )}
            </div>
        </div>
    )
}

